import{n as e,t}from"./jsx-runtime-lw2jiZar.js";import{C as n,E as r,M as i,N as a,O as o,P as s,b as c,j as l,k as u,l as d,n as f,o as p,p as m,t as h,w as g}from"./shared-C5BCElVa.js";import{t as _}from"./earth-DLnLpcYI.js";import{t as v}from"./CodeEditor-BZlrvoTL.js";var y=e(`Send`,[[`path`,{d:`M14.536 21.686a.5.5 0 0 0 .937-.024l6.5-19a.496.496 0 0 0-.635-.635l-19 6.5a.5.5 0 0 0-.024.937l7.93 3.18a2 2 0 0 1 1.112 1.11z`,key:`1ffxy3`}],[`path`,{d:`m21.854 2.147-10.94 10.939`,key:`12cjpa`}]]),b=t();function x({module:e}){return(0,b.jsxs)(a,{children:[(0,b.jsx)(i,{chip:e??`Глава 3 · Блок 10 · HTTP к Planner`,title:`Первый запрос в Postman`,intro:`В занятии 45 мы разобрали method, path и query. Теперь соберём GET в Postman, отправим его серверу Echo и прочитаем ответ. У Planner пока нет HTTP API, поэтому Echo не меняет его задачи.`,tags:[{icon:(0,b.jsx)(y,{size:14}),label:`собираем и отправляем GET`},{icon:(0,b.jsx)(_,{size:14}),label:`проверяем ответ Echo`}]}),(0,b.jsxs)(s,{number:`00`,title:`От договора к настоящему обмену`,children:[(0,b.jsx)(o,{children:`Вспомним основу. Method говорит, что делает запрос. Path выбирает операцию на сервере. Query передаёт дополнительные значения. Сегодня отправим GET к Echo и проверим его ответ.`}),(0,b.jsx)(`p`,{children:`Модель из прошлого занятия описывает запрос, но сама его не отправляет. Теперь добавится новый шаг: Postman передаст GET по сети, а Echo покажет полученные данные. Так мы проверим путь от черновика запроса до ответа.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Точка старта`,description:`Method и path выбраны, query задаёт параметры чтения.`},{title:`Новый вопрос`,description:`Как отправить GET и увидеть ответ сервера?`},{title:`Результат`,description:`Сохраним GET в Postman и проверим ответ Echo.`}]}),(0,b.jsx)(`p`,{children:`Сначала разберём роли, затем настроим Postman и отправим запрос. Echo выступает отдельным учебным сервером. Его ответ не меняет задачи Planner. В конце у нас останутся сохранённый GET и Echo environment для занятия 46.1.`})]}),(0,b.jsxs)(s,{number:`01`,title:`Postman отправляет, Echo отвечает`,children:[(0,b.jsx)(o,{children:`Postman работает как HTTP-клиент: в нём мы заполняем запрос и отправляем его по сети. Echo выступает сервером: он получает запрос и возвращает ответ. Planner в этом обмене не участвует.`}),(0,b.jsx)(`p`,{children:`Представим почтовое окно. Мы отдаём письмо и получаем отметку о доставке. Она подтверждает, что письмо дошло до окна, но не доказывает, что другая служба выполнила просьбу. Echo так же показывает, какие данные получил, но не читает задачи и не применяет правила Planner.`}),(0,b.jsx)(h,{caption:`Запрос к Echo и ответ в Postman`,children:(0,b.jsxs)(p,{label:`Путь запроса и ответа`,children:[(0,b.jsx)(d,{title:`Postman, отправка`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Собираем GET и query`})}),(0,b.jsx)(f,{label:`HTTP request`}),(0,b.jsx)(d,{title:`Echo`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Получает запрос и формирует ответ`})}),(0,b.jsx)(f,{label:`HTTP response`}),(0,b.jsx)(d,{title:`Postman, результат`,shape:`process`,children:(0,b.jsx)(`p`,{children:`Показывает status и body`})})]})}),(0,b.jsx)(`p`,{children:`На широком экране схема читается слева направо, на узком сверху вниз. Сначала Postman отправляет request в Echo. Затем Echo возвращает response в Postman. Это два момента одного обмена. Planner в нём не участвует.`}),(0,b.jsx)(m,{prompt:`Соединим участника с его ролью.`,leftTitle:`Участник`,rightTitle:`Роль`,pairs:[{left:`Postman`,right:`Собирает и отправляет request`},{left:`Echo`,right:`Получает request и возвращает response`},{left:`Мы`,right:`Проверяем ответ`}],explanation:`Postman отправляет запрос, Echo отвечает. Чтобы проверить Planner, запрос нужно отправить его собственному API.`}),(0,b.jsx)(`p`,{children:`API позволяет обращаться к возможностям приложения. Сейчас Postman отправляет запрос в Echo, чтобы проверить его форму. Позже похожий запрос можно будет отправить в собственный API Planner.`})]}),(0,b.jsxs)(s,{number:`02`,title:`До Send мы редактируем запрос`,children:[(0,b.jsx)(o,{children:`В Postman запрос и ответ показаны в разных областях. Пока мы не нажали Send, сервер ничего не получил. Мы редактируем только черновик.`}),(0,b.jsx)(`p`,{children:`В request выберем method и URL. Вкладка Params добавляет query к адресу. Headers содержит заголовки запроса, а Body содержит его данные. В этом GET Body оставляем пустым. После Send в отдельной области response появятся status, заголовки и полученные данные в body.`}),(0,b.jsx)(`p`,{children:`Заголовки есть и у request, и у response. Это заголовки двух разных сообщений. Status относится только к response. Поэтому не ищите его среди полей исходящего GET и не путайте Params запроса с body ответа.`}),(0,b.jsx)(`p`,{children:`Это похоже на бланк до отправки. Пока он у нас, получатель не знает, что в нём написано. После отправки приходит ответ. В Postman request и response тоже остаются разными сообщениями.`}),(0,b.jsx)(g,{title:`От черновика к ответу`,label:`ПОСЛЕДОВАТЕЛЬНОСТЬ`,prompt:`Расставим шаги: сначала выберем адрес, затем проверим полученный ответ.`,pieces:[{id:`environment`,code:`Выбираем Echo и проверяем base_url`},{id:`request`,code:`Настраиваем GET и Params`},{id:`send`,code:`Нажимаем Send`},{id:`response`,code:`Читаем status и body`},{id:`conclusion`,code:`Сравниваем ответ с ожиданием`}],correctOrder:[`environment`,`request`,`send`,`response`,`conclusion`],explanation:`Сначала выберите Echo и настройте request. После Send прочитайте status и body, затем сравните ответ с ожиданием.`,incorrectExplanation:`До Send сервер не видел запрос. Сначала настройте GET, затем нажмите Send и прочитайте response.`}),(0,b.jsx)(`p`,{children:`Названия вкладок могут немного отличаться в разных версиях Postman. Смотрите, относится ли поле к request или response. Например, Body запроса и body ответа это разные поля.`})]}),(0,b.jsxs)(s,{number:`03`,title:`Адрес ведёт к endpoint Echo`,children:[(0,b.jsxs)(o,{children:[`Для первого обращения используем адрес `,(0,b.jsx)(`code`,{children:`https://postman-echo.com/get`}),`. Схема `,(0,b.jsx)(`code`,{children:`https`}),` и host `,(0,b.jsx)(`code`,{children:`postman-echo.com`}),` задают сервер, а path `,(0,b.jsx)(`code`,{children:`/get`}),` указывает его endpoint для получения запроса GET.`]}),(0,b.jsxs)(`p`,{children:[`Endpoint означает операцию сервера, которую выбирает пара method и path. GET `,(0,b.jsx)(`code`,{children:`/get`}),` не является локальным файлом или именем Python-функции. Адрес несуществующего Planner API тоже не станет работающим сервером.`]}),(0,b.jsxs)(`p`,{children:[`В environment `,(0,b.jsx)(`code`,{children:`Echo`}),` мы сохраним только базовый адрес `,(0,b.jsx)(`code`,{children:`https://postman-echo.com`}),`. Тогда в запросе останется запись `,(0,b.jsx)(`code`,{children:`{{base_url}}/get`}),`, а Postman подставит активное значение переменной. Перед отправкой полезно проверить раскрытый URL целиком: так мы убеждаемся, что запрос направлен на Echo, а path не попал внутрь base_url.`]}),(0,b.jsxs)(`p`,{children:[`Схема `,(0,b.jsx)(`code`,{children:`https`}),` задаёт способ обмена, host указывает сервер, а path выбирает операцию. Не добавляйте `,(0,b.jsx)(`code`,{children:`/get`}),` в `,(0,b.jsx)(`code`,{children:`base_url`}),`: иначе он повторится в request.`]}),(0,b.jsx)(c,{question:`В адресе https://postman-echo.com/get что указывает на сервер Echo?`,options:[`Локальный путь /get на компьютере`,`Схема https и host postman-echo.com, вместе с path endpoint`,`Имя будущей Python-функции PlannerService`],correctIndex:1,explanation:`Запрос уходит на host postman-echo.com, а path /get выбирает endpoint этого сервера. Локальный PlannerService здесь не вызывается.`}),(0,b.jsx)(`p`,{children:`Если адрес не разрешается или соединение не устанавливается, серверный response может не прийти. Это отличается от HTTP-статуса 404: при 404 сервер всё же ответил, а при сбое соединения мы не можем прочитать его status. Сначала выясняем, был ли ответ, и только потом разбираем код.`})]}),(0,b.jsxs)(s,{number:`04`,title:`Params добавляет query к GET`,children:[(0,b.jsxs)(o,{children:[`Query передаёт небольшие настройки вместе с URL. Во вкладке Params мы вводим пары имя и значение, а Postman показывает их в адресе после `,(0,b.jsx)(`code`,{children:`?`}),`; несколько пар разделяются знаком `,(0,b.jsx)(`code`,{children:`&`}),`.`]}),(0,b.jsxs)(`p`,{children:[`До нашей практики посмотрим на другой набор: `,(0,b.jsx)(`code`,{children:`city=Kazan`}),` и `,(0,b.jsx)(`code`,{children:`days=2`}),`. Адрес GET может передать эти значения как query, а Echo вернёт их в поле `,(0,b.jsx)(`code`,{children:`args`}),`. На URL они выглядят как текст. Ответ не доказывает, что Echo знает, сколько дней длится поездка или что нужно сделать с городом.`]}),(0,b.jsx)(v,{caption:`Учебный пример: Echo отражает query в args`,code:`GET https://postman-echo.com/get?city=Kazan&days=2

Ожидаемый фрагмент response body:
{
  "args": {
    "city": "Kazan",
    "days": "2"
  }
}`}),(0,b.jsxs)(`p`,{children:[`В этом примере `,(0,b.jsx)(`code`,{children:`"2"`}),` в ответе является строкой, потому что query передаётся в URL как текст. Имя `,(0,b.jsx)(`code`,{children:`days`}),` само по себе не придаёт значению числовой тип. Позже другой сервер может разобрать строку и проверить её по своим правилам, но Echo лишь показывает полученную пару.`]}),(0,b.jsxs)(`p`,{children:[`В нашем GET мы используем `,(0,b.jsx)(`code`,{children:`is_done=false`}),` и `,(0,b.jsx)(`code`,{children:`limit=2`}),`. Эти названия напоминают будущие настройки списка Planner, но в Echo это просто имена query-параметров. Сервер Planner ещё не получает запрос, поэтому список задач не фильтруется и не ограничивается.`]}),(0,b.jsx)(c,{question:`Echo вернул в args значения is_done="false" и limit="2". Что мы узнали?`,options:[`Echo получил и отразил две текстовые query-пары`,`Planner нашёл открытые задачи и оставил только две`,`Echo преобразовал значения в bool и int`],correctIndex:0,explanation:`Поле args показывает, какие текстовые значения Echo получил в query. Оно не говорит о фильтрации данных Planner и не подтверждает преобразование типов.`}),(0,b.jsx)(`p`,{children:`Поэтому мы сравниваем не только имена параметров, но и их фактическое представление. Если пара отсутствует в args, проверяем Params и адрес; если она есть как строка, делаем только вывод о передаче этой строки.`}),(0,b.jsx)(`p`,{children:`Query передаёт короткие значения для чтения, например фильтр или лимит. В этом занятии мы сохраняем две пары и проверяем их в ответе Echo; создание и изменение данных разберём позже.`})]}),(0,b.jsxs)(s,{number:`05`,title:`Ответ подтверждает только то, что мы проверили`,children:[(0,b.jsx)(o,{children:`После отправки GET сначала убеждаемся, что HTTP-ответ вообще получен. Затем проверяем status, при необходимости headers, и нужные значения в body. Каждый признак отвечает на свой вопрос.`}),(0,b.jsxs)(`p`,{children:[`Для обычного запроса к Echo ожидаем status `,(0,b.jsx)(`code`,{children:`200`}),` и JSON в body. Поле `,(0,b.jsx)(`code`,{children:`args`}),` должно содержать query, которую мы отправили. Status 200 сообщает, что Echo ответил успешно; наличие нужных пар проверяется отдельно в `,(0,b.jsx)(`code`,{children:`args`}),`. Одного зелёного индикатора недостаточно, если нас интересует конкретное значение.`]}),(0,b.jsx)(`p`,{children:`Заголовки ответа могут указать формат содержимого. В нашем примере body читается как JSON, но это не значит, что JSON уже записан в файл Planner. Response принадлежит серверу из URL. Чтобы доказать изменение приложения, нужно обращаться к его собственному API и проверять его результат.`}),(0,b.jsx)(n,{code:`GET https://postman-echo.invalid/get`,question:`Postman сообщает, что не может разрешить host. Какой вывод здесь точный?`,options:[`Echo вернул HTTP 404, но Postman скрыл body`,`HTTP response мог не прийти, поэтому status пока нет`,`Planner отверг query и не сохранил задачу`],correctIndex:1,explanation:`Ошибка разрешения host возникает до чтения HTTP-ответа. Без response у нас нет серверного status, а Planner в этом обращении не участвовал.`,fix:`Проверим написание host, активное окружение и раскрытое значение base_url, затем повторим GET к Echo.`}),(0,b.jsx)(`p`,{children:`При status 404 сервер ответил, и его body доступно. При ошибке соединения ответа может не быть, поэтому status 404 или 500 указывать нельзя.`})]}),(0,b.jsxs)(s,{number:`06`,title:`Сохраняем запрос и адрес отдельно`,children:[(0,b.jsxs)(o,{children:[`Collection хранит сохранённые HTTP-запросы, а environment хранит значения, которые зависят от выбранной цели. Для этого занятия запрос останется в `,(0,b.jsx)(`code`,{children:`Planner HTTP Lab`}),`, а базовый адрес Echo будет в environment `,(0,b.jsx)(`code`,{children:`Echo`}),`.`]}),(0,b.jsxs)(`p`,{children:[`Представим папку с карточками рецептов и отдельную наклейку с адресом кухни. В карточке остаётся способ приготовить блюдо, а адресная наклейка помогает выбрать место, куда отправить заказ. В Postman collection сохраняет method, URL-шаблон и Params, а environment задаёт значение `,(0,b.jsx)(`code`,{children:`base_url`}),`. Такая аналогия не означает, что collection хранит задачи или environment запускает сервер.`]}),(0,b.jsxs)(`p`,{children:[`Workspace в Postman содержит collections и environments. Откройте текущий workspace, найдите `,(0,b.jsx)(`code`,{children:`Planner HTTP Lab`}),` и выберите `,(0,b.jsx)(`code`,{children:`Echo`}),`. Откройте GET из collection или создайте его там. `,(0,b.jsx)(`code`,{children:`Send`}),` отправляет текущий запрос, а `,(0,b.jsx)(`code`,{children:`Save`}),` сохраняет его в collection. После добавления Params сохраните GET и снова откройте его из collection, чтобы проверить сохранённую версию.`]}),(0,b.jsxs)(`p`,{children:[`В environment `,(0,b.jsx)(`code`,{children:`Echo`}),` значение `,(0,b.jsx)(`code`,{children:`base_url`}),` равно `,(0,b.jsx)(`code`,{children:`https://postman-echo.com`}),`, без `,(0,b.jsx)(`code`,{children:`/get`}),` и query. Полный request строится как `,(0,b.jsx)(`code`,{children:`{{base_url}}/get`}),`. Если мы сменим активное environment, Postman может подставить другой адрес, но это не меняет смысл сохранённого GET. Поэтому перед Send сверяем активную цель.`]}),(0,b.jsxs)(`p`,{children:[`Если `,(0,b.jsx)(`code`,{children:`Planner HTTP Lab`}),` и `,(0,b.jsx)(`code`,{children:`Echo`}),` уже существуют, используем их и проверяем настройки. Не создаём второй набор ресурсов и не удаляем сохранённый POST, если он остался после прежней версии занятия. Если ресурсов ещё нет, создаём только недостающие в текущем workspace. Для сохранения может понадобиться доступ к workspace; отправка запроса и сохранение collection являются разными возможностями интерфейса.`]}),(0,b.jsx)(`p`,{children:`Экспортировать collection и environment сейчас не требуется. Сначала убедимся, что GET повторяется из сохранённой collection. В следующем подзанятии к той же collection добавим POST с JSON, затем отдельно проверим экспорт и импорт обоих ресурсов.`}),(0,b.jsx)(r,{tone:`info`,children:`Если Postman просит войти, используем уже доступную учётную запись или отмечаем, что сохранение заблокировано. Новый аккаунт и платные возможности не являются частью этой практики.`})]}),(0,b.jsxs)(s,{number:`07`,title:`Что мы будем делать в практике`,children:[(0,b.jsx)(o,{children:`Теперь мы используем модель запроса как рабочую проверку: адрес и метод уже определены, а результат доказывает только то, что Echo действительно получил.`}),(0,b.jsx)(u,{variant:`connected`,items:[{title:`Подготовим контекст`,description:`Проверим существующие Planner HTTP Lab и Echo, активный base_url и не будем создавать дубликаты.`},{title:`Отправим GET`,description:`Сначала проверим /get без query, затем добавим is_done=false и limit=2 через Params.`},{title:`Сохраним наблюдение`,description:`Откроем GET из collection и сверим status 200 и строковые значения в args.`}]}),(0,b.jsx)(`p`,{children:`Проверим ресурсы Postman и раскрытый URL, отправим GET без query, затем добавим две пары, сохраним запрос и повторим его. Если соединение не установлено, отметим это как сетевой сбой: HTTP status ещё нет.`}),(0,b.jsx)(`p`,{children:`На выходе у нас будет сохранённый GET и выбранный Echo environment. Этот результат станет входом занятия 46.1: мы добавим к тому же набору POST с JSON и проверим восстановление после экспорта и импорта. В занятии 46 мы не отправляем JSON, не экспортируем файлы и не меняем Planner.`}),(0,b.jsx)(l,{text:`Проверим GET к Echo с query, сохраним его в Planner HTTP Lab и сверим фактический ответ.`})]})]})}export{x as Lesson46};